(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["bg"] = {"ui":{"skip":"Към съдържанието","back":"← Обратно към AI-gile","lang.button":"Език: {name}","lang.dialog":"Избери език","lang.search":"Търси език","lang.none":"Няма съвпадащ език","lang.notYet":"{name} още не е преведен","theme.aria":"Смяна на темата: светла, тъмна или черна","theme.toLight":"Към светла тема","theme.toDark":"Към тъмна тема","theme.toBlack":"Към черна тема (истинско черно, щадящо OLED екраните)","words.underline":"Подчертай тези думи на страницата","words.underlineHelp":"Посочи или докосни дума с точки отдолу, за да видиш какво означава.","index.title":"AI-gile: твоят AI екип за разработка, на една дъска","index.description":"AI-gile е канбан дъска за екипи, които кодират с изкуствен интелект. Те работят, докато спиш; ти получаваш една кратка купчинка неща за решаване, тестване и приемане.","hero.logoAlt":"Икона на дъската на AI-gile","hero.h1.html":"Твоят AI екип за разработка, на една&nbsp;дъска.","hero.alpha":"🐣 Затворена пре-алфа","hero.alphaTitle":"Рано и недовършено: благодаря, че го пробваш!","hero.lede":"Те строят, докато спиш. Събуждаш се с една кратка купчинка: няколко въпроса, няколко неща за тестване, един-два лилави диаманта. Кликваш, приемаш и се връщаш към кафето си.","dl.windows":"Приложение за Windows","dl.browser":"Пусни го в браузъра","dl.messenger":"📱 Messenger за телефона ти","dl.soon":"Скоро","dl.notify":"🔔 Кажи ми, когато отвори","dl.notifySmall":"Алфа или бета","hero.secondary":"Аджайл, но екипът никога не се нуждае от кафе за стендъп. (Правят стендъпи така или иначе.)","pitch.h2":"AI-gile с колкото думи искаш","pitch.lede":"Избери дължина, от една дума до 144. Всяка дължина е отделно описание, написано за този размер. Плъзни плъзгача или използвай стрелките.","pitch.rangeLabel":"Дължина в думи","pitch.dice":"🎲 друга версия","pitch.words.one":"{n} дума","pitch.words.other":"{n} думи","pitch.letters.one":"{n} буква","pitch.letters.other":"{n} букви","pitch.chars.one":"{n} знак","pitch.chars.other":"{n} знака","count.line.html.one":"{n} карта на дъската в момента","count.line.html.other":"{n} карти на дъската в момента","people.humans.html.one":"👥 {n} човек","people.humans.html.other":"👥 {n} души","people.agents.html.one":"🤖 {n} агент","people.agents.html.other":"🤖 {n} агента","people.working.html.one":"⚡ {n} работи в момента","people.working.html.other":"⚡ {n} работят в момента","pre.title":"AI-gile: тук се строи нещо","pre.description":"Тук се строи нещо. Дъска, на която AI екипи създават каквото поискаш и те учат по пътя. Засега затворена пре-алфа с приятели.","pre.h1":"Тук се строи нещо. 🤫","pre.line":"Дъска, на която AI екипи създават каквото поискаш и те учат по пътя. Засега затворена пре-алфа с приятели.","pre.btn":"🔔 Кажи ми, когато отвори","pre.peek":"Зад стъклото: истинската дъска, на живо. Всяка карта е цветна лента.","pre.peekFake":"Зад стъклото: така изглежда дъска в работа.","features.aria":"Какво прави","f.pile.h":"Една купчинка за теб","f.pile.html":"<b>За теб</b> събира всичко, което чака теб, във всички проекти: въпроси, неща за тестване, задачи, които може да свърши само човек. Опашката ти казва кое е следващо и колко ще отнеме.","f.sleep.h":"Екипи, които работят, докато спиш","f.sleep.p":"Всеки проект има лидер и екип от AI агенти. Коментирай карта и екипът се събужда, върши работата и ти я връща със стъпки, които един уморен човек може да следва.","f.tester.h":"Първо проверява AI тестер","f.tester.p":"Преди нещо да стигне до теб, тестер следва стъпките в копие на приложението и показва какво е видял, със снимка на екрана. Прегледай миналите и приеми с един клик.","f.proof.h":"Доказателства, не обещания","f.proof.p":"Всяко предаване показва какво се е променило: файловете, разликата, снимките на екрана. Не е нужно да отваряш всяко приложение, за да видиш дали е готово.","f.chat.h":"Чати с лидерите си","f.chat.p":"Странична лента като в Discord: една икона за проект, лилави диаманти за онова, което чака теб. Пиши на лидер идея; той я превръща в карти и план, с бутон ✅ Давай.","f.tidy.h":"Подрежда се сам","f.tidy.p":"Сродните карти се сливат в една, объркани заглавия се оправят, а проверка на токените държи кода компактен. По-малко неща за превключване, по-малко за мислене.","f.private.h":"Твое, на твоя компютър","f.private.li1":"Дъската работи на твоята собствена машина и отговаря само на теб.","f.private.li2":"Личните съобщения между хората са шифровани от край до край.","f.private.li3":"Без акаунти, без тракери, без бисквитки.","f.lang.h":"На твоя език","f.lang.p":"Над 120 езика, от нидерландски, уелски и японски до пиратски, Йода и клингонски, с бързо превключване обратно към английски за професионалния жаргон.","f.service.h":"От идея до истинска услуга","f.service.p":"Създал си с AI нещо, което хората вече ползват? Отбележи го като услуга и дъската ще ти помогне да го поддържаш добре: проверки на работоспособността, публична страница за състоянието, инциденти с анализ, промени, които искат Go, резервни копия, проверявани всеки ден. Помощта те учи на всяка стъпка по пътя.","msgr.h2":"AI-gile Messenger: екипът ти в джоба","msgr.p1":"Говори с AI екипа си, без да отваряш таблото. Пиши си с лидерите на проектите и с приятелите си, виж стъпките за тест на карта и им отговори, всичко от телефона.","msgr.p2":"За да го свържеш, сканирай QR код от таблото си. За първи път? Приятелски демо чат ще те разведе.","msgr.when":"Първо за Android, после уеб версия за телефони и iPhone.","msgr.who":"Лидерът на проекта ти","msgr.b1":"Поправката на тъмния режим е готова. Искаш ли стъпките за тест?","msgr.b2":"Да, моля!","msgr.b3":"1. Отвори Настройки. 2. Избери Тъмна. Изглежда ли наред?","tl.aria":"Времева линия от първия разговор до пътната карта","tl.h2":"От първия чат до следващото","tl.lede":"Истински дати и часове, в твоята часова зона. След днес това е планът, без обещани дати.","tl.today":"Днес","tl.planned":"планирано","tl.doing":"в процес","tl.cards.one":"{n} карта","tl.cards.other":"{n} карти","join.h2":"Включи се","join.lede":"AI-gile се прави от един брадат чудак с AuDHD и няколко битки с психичното здраве, и от много търпеливи агенти. Засега е частен, в затворена алфа с приятели. Искаш ли да го пробваш, когато се отвори?","join.btn":"Заяви интерес","join.small":"Ще ти пишем по имейл, нищо друго","footer.tag":"AI-gile. Без тракери, без бисквитки, без кафе за стендъп.","footer.licence":"Бизнес лиценз","footer.status":"Статус","footer.privacy":"Какво пазим","footer.thanks":"Разговорите благодарение на ChilledChat","form.sending":"Изпраща се…","form.failed":"Не се получи: опитай пак по-късно.","form.offline":"Не успяхме да стигнем до AI-gile: опитай пак по-късно.","form.keep":"Използваме това само за да ти отговорим, после го изтриваме. Без тракери, без бисквитки.","form.keepLink":"Какво пазим","interest.title":"AI-gile: кажи ми, когато алфата се отвори","interest.description":"Остави имейла си, за да научиш кога се отваря затворената алфа или бета на AI-gile.","interest.h1":"🔔 Кажи ми, когато отвори","interest.lede":"AI-gile е в затворена пре-алфа. Остави имейла си и ще ти пишем веднъж, когато има място за теб.","interest.email":"Твоят имейл","interest.which":"Кой тест?","interest.alpha":"Затворена алфа: рано, грубо, много промени","interest.beta":"Бета: по-стабилна, по-късно","interest.both":"Която и да е, която дойде първа","interest.submit":"Запиши ме в списъка","interest.thanks":"Благодаря! В списъка си.","licence.title":"AI-gile: бизнес лиценз","licence.description":"Използваш ли AI-gile в бизнеса си? Кандидатствай за безплатен бизнес лиценз.","licence.h1":"📜 Бизнес лиценз","licence.lede":"Използваш ли AI-gile на работа? Кажи ни кой си и с какво се занимаваш. Ако върши някаква полза, лицензът е безплатен.","licence.company":"Компания","licence.website":"Уебсайт","licence.what":"С какво се занимаваш","licence.how":"Как помага на света","licence.email":"Имейл","licence.submit":"Кандидатствай","licence.thanks":"Благодаря! Ще ти отговорим по имейл.","status.title":"Статус на AI-gile","status.h1":"Статус на AI-gile","status.quiet":"Всичко е тихо","status.intro":"Работи ли AI-gile в момента? Тази страница проверява сайта, споделянето на дъски, разговорите и изтеглянето на всеки 5 минути.","status.up":"Работи (отговори за {ms} ms)","status.slow":"Не отговори на последната проверка, опитваме пак","status.down":"Не работи: не отговори на последните две проверки","status.svc.web":"Уебсайт","status.svc.web.offers":"Този сайт: какво е AI-gile и формата за интерес","status.svc.boards":"Споделяне на дъски","status.svc.boards.offers":"Публични дъски, съобщения между приятели и покани","status.svc.calls":"Разговори","status.svc.calls.offers":"Глас, видео и споделяне на екрана в AI-gile","status.svc.download":"Изтегляне","status.svc.download.offers":"Инсталаторът за Windows и линковете за покани","status.checking":"Проверява се…","status.offline":"В момента не може да се стигне до услугата за статус (опитва се пак)","status.updated":"обновено {ago}","status.justNow":"току-що","status.min":"преди {n} мин","status.hours":"преди {n} ч","status.days":"преди {n} д","privacy.title":"AI-gile: какво пазим","privacy.h1":"Какво пазим","privacy.lede":"Накратко: само това, което ни пращаш, и не за дълго.","privacy.only":"Само това, което ни пращаш: каквото напишеш във формата, например имейла си. Нищо друго за теб.","privacy.sealed":"Запечатва се, така че сървърът ни да не може да го прочете: в браузъра ти, преди да тръгне (при по-стар браузър – в момента, в който пристигне). Само нашата собствена дъска може да го отвори.","privacy.server":"Изтрива се от сървъра веднага щом стигне до дъската ни. Всичко, което още е там след 30 дни, се изтрива така или иначе.","privacy.board":"Пазим го на дъската си само докато ти отговорим, после го изтриваме и оттам.","privacy.none":"Без тракери, без бисквитки, без анализи.","privacy.local":"Езикът ти и изборът на светла или тъмна тема остават в собствения ти браузър. Никога не ни се изпращат.","privacy.ask":"Искаш да изчезне по-рано? Отговори на имейла ни и ни кажи.","live.h2":"Гледайте как се изгражда, на живо","live.caption":"Всяка карта е скрита: виждате формата на работата, не думите.","live.watching.one":"на живо: {n} гледа","live.watching.other":"на живо: {n} гледат","live.last.now":"Последната карта е преместена току-що","live.last.min.one":"Последната карта е преместена преди {n} мин","live.last.min.other":"Последната карта е преместена преди {n} мин","live.last.hour.one":"Последната карта е преместена преди {n} час","live.last.hour.other":"Последната карта е преместена преди {n} часа","live.last.day.one":"Последната карта е преместена преди {n} ден","live.last.day.other":"Последната карта е преместена преди {n} дни","live.offline":"Таблото на живо си почива за малко. Заповядайте пак скоро.","live.cols":"Backlog|За изпълнение|В процес|Екипът проверява|Чака твоя тест|За екипа|Готово"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Канбан.","Роботи.","Делегирано."]},{"n":2,"texts":["Роботи, канбан.","Агенти, подредени.","Идеи, построени."]},{"n":3,"texts":["Канбан за роботи.","Идеите стават функции.","Безплатен канбан за агенти."]},{"n":5,"texts":["Канбан дъска, водена от агенти.","Ти пишеш карти. Агентите строят.","Безплатно, локално, тествано, малко смахнато."]},{"n":8,"texts":["Безплатна канбан дъска, където работят AI агенти.","Напиши идея. Агентите я строят. Ти я приемаш.","Аджайл за един човек и много търпеливи роботи."]},{"n":13,"texts":["Канбан дъска на твоя компютър, където AI агентите поемат картите и ги изпълняват.","Напиши идея. Екип от агенти я строи. Тестер я проверява накрая.","Безплатно, без акаунти, без тракери: дъска, няколко робота и ти, който решаваш."]},{"n":21,"texts":["AI-gile е канбан дъска за работа с AI агенти за кодиране. Те поемат картите, а ти ги тестваш и приемаш.","Всеки проект получава лидер и екип от AI агенти. Коментирай всяка карта и екипът се залавя за работа.","Безплатна лична дъска със задачи, която работи на твоя компютър. Работниците са роботи. Този, който казва да, си ти."]},{"n":34,"texts":["Слагаш идеи на дъска. Екип от AI агенти ги превръща в работещи функции, тества ги и ти ги връща със стъпки за изпробване. Нищо не се брои за готово, докато ти не кажеш.","AI-gile е домашно направена канбан дъска, която Рич построи с голяма помощ от агентите, които сега управлява. Безплатна е, работи на твоя компютър и се споделя с приятели, не се продава.","Представи си обикновена канбан дъска с колони от Backlog до Готово, само че картите се поемат от AI агенти. Те докладват напредъка, питат, когато заседнат, и винаги чакат твоето одобрение."]},{"n":55,"texts":["AI-gile е канбан дъска, на която екипът е съставен от AI агенти. Всеки проект има лидер, който планира работата, и помощници, които я строят. Когато една функция е готова, AI тестер я изпробва и прави снимка на екрана, след което тя пристига в твоята купчинка. Приеми я или коментирай и те я правят наново.","Започна като начин един човек да следи много сесии за кодиране с AI едновременно и порасна до истинска дъска. Работи на твоята машина, не иска акаунт и няма тракери. Безплатна е за приятели и за всеки любопитен. Също така е недовършена, така че очаквай някоя и друга грапавина и от време на време изненада.","Ето честната версия. Все още трябва ти да измисляш идеите и ти да проверяваш резултатите. AI-gile върши всичко помежду им: подрежда картите, буди правилния агент, когато коментираш, показва точно какво се е променило и държи всичко в една кратка купчинка за теб, без излишен шум."]},{"n":89,"texts":["AI-gile е безплатна канбан дъска, която пускаш на собствения си компютър. Вместо хора всеки проект има екип от AI агенти: лидер, който превръща идеите ти в карти и план, и помощници, които поемат картите по приоритет. Когато нещо е построено, AI тестер следва стъпките за тестване и ти показва какво е видял. После то чака в една купчинка, наречена За теб. Приемаш го или коментираш и екипът опитва отново. Нищо никога не стига до Готово без теб.","Има и функции, които може да не очакваш. Нощна стража държи колоната За правене пълна, докато спиш, като избира карти, които не искат отговор от теб. Брояч на токени показва колко са използвали агентите днес и тази седмица, а Режим без токени им казва да спрат да харчат. Можеш да пишеш на приятели, а личните съобщения са шифровани от край до край. Дъската говори около 120 езика, включително нидерландски, фламандски, пиратски и клингонски. Нищо от това не струва и стотинка и никой не се опитва да ти го продава.","AI-gile е малък личен проект, не компания. Рич искаше да се грижи за няколко проекта с AI кодиране, без да отваря всяко приложение, за да ги проверява, затова двамата с агентите построиха дъска за това, а после я използваха, за да построят останалата част от себе си. В затворена пре-алфа е, което значи, че работи, повечето време, за шепа приятели. Няма страница с цени, няма бюлетин и няма план за растеж. Ако ти звучи полезно, можеш да поискаш да го пробваш, когато се отвори малко повече."]},{"n":144,"texts":["AI-gile е канбан дъска за един човек и много AI агенти. Работи на твоя собствен компютър и е напълно безплатна. Добавяш проекти и всеки проект получава лидер и малък екип. Чатиш с лидера, малко като в Discord, и описваш идея; лидерът я превръща в карти и план, после чака да натиснеш Давай. Екипът минава през картите по приоритет, като използва прост команден ред, направен за езикови модели. Преди нещо да се върне при теб, AI тестер следва стъпките в копие на приложението и прикрепя снимка на екрана. Готовата работа пристига в твоята купчинка с променените файлове и разликата. Приемаш я или оставяш коментар, и екипът се събужда и опитва пак. Само ти можеш да преместиш карта в Готово.","Един ден с AI-gile, приблизително. Вечерта оставяш няколко коментара: този бутон е на грешно място, този списък трябва да е подреден, можем ли да имаме тъмен режим. Лягаш си. Агентите четат коментарите, правят промените, тестват ги и ти ги връщат. Ако За правене се изпразни, нощната стража го допълва от backlog с карти, които не искат отговор от теб. Сутринта има една кратка купчинка: няколко въпроса и няколко неща за изпробване, всяко със стъпки, които може да следва един сънлив човек, и със снимка на екрана как работи. Кликваш, приемаш добрите и връщаш останалите. Брояч на токени показва какво е изразходвано, а Режим без токени е за оскъдните седмици. После закусваш, с което агентите още не могат да помогнат.","Първо, какво AI-gile не е. Не е стартъп, не се продава и никой не събира данните ти. Безплатна дъска е, която работи на твоя компютър, без акаунти, без тракери и без бисквитки. Какво е: едно подредено място да видиш всички проекти с AI кодиране наведнъж, с екип от агенти, който върши картите, и ти, който взимаш решенията. Слива сродните карти, оправя объркани заглавия и следи колко компактен остава кодът. Говори около 120 езика, от нидерландски и фламандски до пиратски и клингонски. Приятелите могат да си пишат, лично и шифровано. Направена е от Рич и много търпеливи агенти, най-вече като използват самата нея. В затворена пре-алфа е, така че на места е грапава. Ако ти звучи забавно, попитай любезно и може да влезеш рано."]}],"quips":{"1":"Една дума. Смело. Може би твърде смело.","3":"Три думи. Вече по-честно от повечето страници на продукти.","8":"Осем думи. Пак по-кратко от стендъп.","21":"Дължините са story points, между другото. Разбира се, че са.","55":"Петдесет и пет думи. Две карти се довършиха, докато четеше това.","144":"Това е дългата. Няма 233. Агентите си легнаха."}},"timeline":{"first-idea.name":"Първата идея","first-idea.line":"Най-първият разговор, преди да съществува и един ред код.","first-board.name":"Първата дъска","first-board.line":"Дъска, която следи собственото си изграждане: карти, колони, дърпане и пускане, проекти.","team-roles.name":"Екип и роли","team-roles.line":"Профили на агенти, шаблони за екипи, пространства и кой какво прави.","install.name":"Инсталиране и версии","install.line":"Zip, който приятел може да инсталира, самообновяване, канали и връщане назад.","usage-saver.name":"Спестяване на ресурси","usage-saver.line":"Мери колко струват пусканията, дръж кода компактен, пази лимита си.","friends.name":"Приятели и споделяне","friends.line":"Лични съобщения, шифровано реле, покани, роли и споделени проекти.","languages.name":"Езици","languages.line":"Всеки екранен текст в езиков файл, първо нидерландски и фламандски.","ai-tester.name":"AI тестер","ai-tester.line":"Тестер проверява всяко предаване първо и показва какво е видял.","website.name":"Уебсайтът","website.line":"aigile.lol, тийзърът и тази времева линия.","streaming.name":"Чат и стрийминг","streaming.line":"Discord, Twitch, OBS, режим за стриймъри, GIF-ове и емоджита.","no-ai.name":"Версия без AI","no-ai.line":"Дъска за хора, които кодират без AI, и публични дъски.","night-watch.name":"Нощна стража","night-watch.line":"Пазач и Scrum Master държат екипите на задачата, докато спиш.","p-more.name":"Всичко останало","p-more.line":"По-малки идеи, които още чакат реда си.","p-android.name":"Телефон и Android","p-android.line":"Стигай до дъската си от телефона, после и с родно Android приложение.","p-release.name":"Алфа и нататък","p-release.line":"Затворена алфа, живият сайт, после бета.","p-languages.name":"Още езици","p-languages.line":"130 езика и режим на потапяне за учещите.","p-engines.name":"Още AI двигатели","p-engines.line":"Избери Claude, Codex, Gemini, Copilot или Cursor за всеки агент.","p-pro.name":"Професионална практика","p-pro.line":"Етикети за риск, врати за сливане, карти за инциденти и предпазни огради.","p-self.name":"Грижа за теб","p-self.line":"Режим на умора, напомняния за грижа за себе си и 4:20.","p-servers.name":"Сървъри и мащаб","p-servers.line":"Глобални настройки на сървъра, роли и планиране за растеж.","p-livestream.name":"Допълнения за стрийминг","p-livestream.line":"Twitch чат, собствени емоджита и публичен жив изглед."},"words":{"button":"📖 Професионален жаргон","h":"📖 Обяснени думи","intro":"Думите, които срещаш в AI-gile, на прост език: как се създава, как се променя безопасно, как да продължи да работи за хората, които го ползват, и как се работи като екип с AI.","search":"Търси дума…","none":"Няма дума, която да съвпада.","close":"Затвори","count":{"one":"{count} дума","other":"{count} думи"},"groups":[{"id":"build","name":"🛠️ Създаване"},{"id":"change","name":"🔀 Безопасни промени"},{"id":"run","name":"🛎️ Поддържане на услуга"},{"id":"team","name":"🤝 Работа в екип (и с AI)"}],"list":[{"id":"repo","g":"build","word":"Хранилище","text":"Папката на проекта с код и пълната му история от къмити, обикновено пазена и в GitHub.","also":["хранилище","хранилища","репо","repo","repository"]},{"id":"branch","g":"build","word":"Клон","text":"Отделна линия работа в кода, за да се правят промени, без да се пипа основната версия.","also":["клон","клона","клонове","клоновете","branch","branches"]},{"id":"commit","g":"build","word":"Къмит","text":"Запазена снимка на кода с кратка бележка какво е променено. Винаги можеш да се върнеш към някой.","also":["къмит","къмита","къмити","къмитите","commit","commits"]},{"id":"push","g":"build","word":"Push","text":"Изпращане на запазените снимки (къмити) от този компютър към GitHub, за да са архивирани и споделени."},{"id":"merge","g":"build","word":"Сливане","text":"Връщане на промените от един клон обратно в основната версия."},{"id":"pr","g":"build","word":"Pull request","text":"Искане промените на един клон да бъдат проверени и слети в основната версия.","also":["PR","pull request"]},{"id":"refactor","g":"build","word":"Рефакториране","text":"Подреждане на кода, без да се променя какво прави: по-малки файлове, по-ясни имена, по-малко повторения."},{"id":"bug","g":"build","word":"Бъг","text":"Нещо, което не работи както трябва.","also":["бъг","бъга","бъгове","бъговете","bug","bugs"]},{"id":"test","g":"build","word":"Тест","text":"Изпробване на готова работа, за да се провери дали прави каквото е поискано, преди да я приемеш.","also":["тест","теста","тестове","тестовете","тестване","test","tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Съкращение от quality assurance (осигуряване на качеството): автоматичните проверки, които се пускат, преди нещо да излезе на живо. Когато QA е червено, нещо се е провалило и не може да излезе на живо, докато не се поправи.","also":["проверки на качеството","осигуряване на качеството","quality checks"]},{"id":"deploy","g":"change","word":"Деплой","text":"Пускане на нова версия на живо, например на сървър, където хората я използват."},{"id":"release","g":"change","word":"Версия","text":"Пакет завършена работа с име, който излиза на живо наведнъж, с кратки бележки какво се е променило. 🚀 Версии пише бележките от завършените карти.","also":["версии","релийз","release"]},{"id":"rollback","g":"change","word":"Връщане назад","text":"Връщане към последната версия, която е работила, когато нова създава проблеми. В AI-gile това прави списък за проверка от стъпките за отмяна, записани на всяка промяна.","also":["върни назад","rollback","roll back"]},{"id":"live","g":"change","word":"На живо","text":"Истинската версия, която хората ползват, за разлика от копие за пробване на неща. Разработчиците я наричат и продукция (production).","also":["продукция","продукционна среда","production","live"],"noTip":1},{"id":"change","g":"change","word":"Промяна","text":"Планирана промяна в нещо, на което хората разчитат, първо записана: какво, защо, рискът, кога и как да се отмени. Започни една с 🔀 Подай промяна.","also":["промени","заявка за промяна","change request"],"noTip":1},{"id":"risk","g":"change","word":"Риск","text":"Нещо, което може да се обърка, оценено по това колко е вероятно и колко лошо би било. ⚠️ Рискове ги държи в един списък, с най-високата оценка най-горе, всеки с дата за нов преглед.","also":["рискове","регистър на рисковете"]},{"id":"chgwin","g":"change","word":"Прозорец за промени","text":"Времето, когато промените могат да излизат на живо, например спокойна вечер във вторник. Извън прозорец карта за промяна не може да се завърши, освен ако не е спешна.","also":["прозорци за промени","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Бързо гласуване точно преди промяна да излезе на живо: всеки, който трябва да одобри, казва Go или No go. Продължава само когато са съгласни.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Одобрение","text":"Чакане на „да“, преди да започне работа. Карта, подадена от приятел, или промяна чака в ✅ Одобрения, докато не я одобриш или откажеш.","also":["одобрения","approval"]},{"id":"quiettime","g":"change","word":"Тихо време","text":"Период, например стрийм, демо или нощта, когато нищо не излиза на живо. Екипите продължават да работят и тестват, но излизането на живо чака да свърши. Другаде го наричат замразяване на промените.","also":["тихи времена","замразяване на промените","change freeze"]},{"id":"service","g":"run","word":"Услуга","text":"Нещо, което си създал и на което хората разчитат, като уебсайт или приложение, за което се грижат, за да продължи да работи. Отметни „Този проект е услуга“ и кажи какво предлага, кой го ползва и кой е дежурен.","also":["услуги","service"]},{"id":"uptime","g":"run","word":"Проверка на работоспособността","text":"Автоматична проверка на всеки няколко минути дали услугата ти още отговаря. Ако се провали няколко пъти поред, AI-gile сам отваря карта за инцидент.","also":["работоспособност","uptime","uptime check"]},{"id":"statuspage","g":"run","word":"Страница за състоянието","text":"Публична страница, която показва дали услугата работи (зелено, оранжево или червено) с последната новина, за да могат ползващите я да проверят, вместо да питат.","also":["статус страница","status page"]},{"id":"desk","g":"run","word":"Бюро за обслужване","text":"Мястото, където пристигат въпроси и сигнали от хората, които ползват услугата ти. AI-gile разпределя всеки като заявка, инцидент или идея и казва, ако прилича на нещо, което вече е съобщено.","also":["бюра за обслужване","бюро за помощ","поддръжка"]},{"id":"svcrequest","g":"run","word":"Заявка за услуга","text":"Някой иска нещо обичайно, например нов акаунт или малко помощ, вместо да съобщава, че нещо е развалено. Чака реда си; инцидентът е с предимство.","also":["заявки за услуга"]},{"id":"incident","g":"run","word":"Инцидент","text":"Нещо, което е развалено за хората, които го ползват в момента, например сайтът не работи. Карта 🔥 инцидент минава пред опашката: да проработи отново е на първо място.","also":["инциденти","incident"]},{"id":"major","g":"run","word":"Голям инцидент","text":"Голям инцидент: засегнати са много хора или пари или данни са в риск. Един бутон слага всички екипи върху него (рояк), събужда дежурния и иска обновяване на състоянието на всеки 30 минути.","also":["големи инциденти","major incident"]},{"id":"oncall","g":"run","word":"Дежурство","text":"Да си този, който отговаря, когато нещо се счупи, дори през нощта. Всяка услуга има дежурен член на екипа, когото събуждат първи за нейните инциденти.","also":["дежурен","on call","on-call"]},{"id":"replyby","g":"run","word":"Срок за отговор","text":"Колко дълго една карта може да чака първи отговор, например час за инцидент. След това получава червен часовник, така че нищо да не бъде тихо забравено. Нарича се и цел за отговор.","also":["срокове за отговор","цел за отговор","response target"]},{"id":"postmortem","g":"run","word":"Анализ след инцидента","text":"Кратък поглед назад след инцидент: какво стана, какво помогна и какво да се промени, без да се обвинява никой. Инцидент не може да се затвори без такъв.","also":["post-mortem","postmortem","преглед след инцидент"]},{"id":"problem","g":"run","word":"Проблем","text":"Скритата причина зад един или повече инциденти. Карта 🧩 проблем групира инцидентите, които все се връщат, за да се намери причината и да се поправи завинаги.","also":["проблеми","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Първопричина","text":"Истинската причина нещо да се счупи, а не само това, което си видял да се обърка. Поправи първопричината и инцидентът спира да се връща.","also":["първопричини","основна причина","root cause"]},{"id":"workaround","g":"run","word":"Заобиколно решение","text":"Начин нещата да продължат да работят, докато истинската поправка е готова, например рестартиране на нещо, когато забие. Записва се на картата на проблема, за да не трябва никой да го измисля отново.","also":["заобиколни решения","workaround"]},{"id":"knownerror","g":"run","word":"Известна грешка","text":"Проблем, чиято причина е ясна и който има заобиколно решение, но още не е поправен. 🧩 Известни грешки ги изброява, за да ползват всички заобиколното решение, вместо да ровят отново.","also":["известни грешки","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Инструкции стъпка по стъпка за поправяне на познат вид проблем, за да се прави всеки път по един и същ начин и бързо. След голям инцидент екипът може да предложи такъв, за да го одобриш.","also":["runbooks","наръчник","наръчник за действие"]},{"id":"ci","g":"run","word":"Конфигурационен елемент","text":"Едно нещо, от което зависи услугата ти, например сървър, домейн, сертификат, ключ или доставчик. 🗂️ Конфигурационни елементи ги изброява за всяка услуга, за да виждаш какво засяга даден инцидент и какво трябва да се поднови или архивира.","also":["конфигурационни елементи"]},{"id":"expiry","g":"run","word":"Срок на валидност","text":"AI-gile следи дати като изтичането на сертификат или домейн. До 30 дни преди датата създава една карта за подновяване, за да не спре нищо да работи изневиделица.","also":["срокове на валидност","изтичане","следене на изтичането"]},{"id":"backup","g":"run","word":"Резервно копие","text":"Запазено копие на данните ти от по-рано, на което да се опреш, ако нещо се изгуби или повреди. AI-gile прави резервно копие на дъските ти всеки ден.","also":["резервни копия","бекъп","backup"]},{"id":"restore","g":"run","word":"Възстановяване","text":"Връщане на данни от резервно копие. Резервното копие наистина важи чак когато знаеш, че може да се възстанови, затова си струва да го пробваш от време на време.","also":["възстанови","възстановено","restore"]},{"id":"svcreview","g":"run","word":"Преглед на услугата","text":"Поглед назад към един месец от услугата: отворени и оправени инциденти, колко бързо хората са получили отговор, време на работа и изразходвани токени. Месечният преглед показва това за всяка услуга.","also":["прегледи на услугата","месечен преглед","месечни прегледи"]},{"id":"accessreview","g":"run","word":"Преглед на достъпа","text":"На всеки 90 дни проверка кой все още може да влезе: линкове за споделяне, роли на приятели и пазени тайни. Запазваш или премахваш всеки, за да не остава стар достъп.","also":["прегледи на достъпа"]},{"id":"improvements","g":"run","word":"Списък с подобрения","text":"Всичко, в което екипът реши да стане по-добър, на едно място: предложения от ретро, действия от прегледи и поправки на проблеми, всяко със състоянието си. Намираш го в 📈 Подобрения.","also":["списъци с подобрения","подобрения"]},{"id":"tokencap","g":"run","word":"Лимит на токените","text":"Месечен лимит на токените, които агентите на една услуга могат да използват. При 80% получаваш предупреждение; при 100% фоновата им работа чака до следващия месец или докато не вдигнеш лимита.","also":["лимити на токените"]},{"id":"backlog","g":"team","word":"Backlog","text":"Идеи и работа, които още не са планирани. Нищо там не се върши, докато не се премести в „За изпълнение“."},{"id":"sprint","g":"team","word":"Спринт","text":"Кратък период работа (често седмица или две) с уговорен набор карти за привършване.","also":["спринт","спринта","спринтове","спринтовете","sprint","sprints"]},{"id":"standup","g":"team","word":"Стендъп","text":"Бърза проверка: какво е направил всеки член на екипа, какво ще прави после и какво го спира.","also":["стендъп","стендъпа","стендъпи","стендъпите","standup","stand-up","stand-ups"]},{"id":"kanban","g":"team","word":"Канбан","text":"Табло с колони (За изпълнение, В процес, Готово), в което картите се движат отляво надясно, докато върви работата."},{"id":"wip","g":"team","word":"WIP лимит","text":"Work in progress (работа в процес): най-много карти, които една колона трябва да държи, за да довършва екипът нещата, преди да започне още.","also":["WIP","wip лимит"]},{"id":"dod","g":"team","word":"Определение за „Свършено“","text":"Краткият списък на екипа какво значи „завършено“, например тествано и обяснено, преди картата да ти бъде предадена. Близнакът му, Определението за „Готово за старт“, казва кога картата е достатъчно ясна, за да се започне.","also":["Определение за „Готово за старт“","Definition of Done","Definition of Ready"]},{"id":"testpile","g":"team","word":"Купчина за тестове","text":"Завършените карти, които чакат да ги пробваш, една след друга. Приеми една или я върни с бележка и идва следващата.","also":["купчини за тестове","test pile"]},{"id":"retro","g":"team","word":"Ретро","text":"Поглед назад към това как работи екипът, за да се договори едно нещо за подобрение. В AI-gile ретрото предлага промяна в начина на работа на екипа, а ти казваш Go или Още не.","also":["ретроспектива","retro","retrospective"]},{"id":"peerreview","g":"team","word":"Колегиална проверка","text":"Втори чифт очи: друг AI проверява работата по всяка карта, преди да стигне до теб, така че да минават по-малко грешки.","also":["преглед на кода","peer review","code review"]},{"id":"swarm","g":"team","word":"Рояк","text":"Всички на палубата: всеки екип оставя другата работа, за да помогне по един спешен проект, докато се оправи. Другите проекти междувременно чакат.","also":["swarm","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Този, който поддържа работата в движение: забелязва заседнали карти, побутва екипите и ти напомня какво чака. В AI-gile Lead Scrum Master прави това за всички проекти.","also":["Lead Scrum Master","скръм мастър"]},{"id":"agent","g":"team","word":"Агент","text":"AI, който работи самостоятелно по задача: чете кода, прави промени, пуска проверки и докладва.","also":["агент","агента","агенти","агентите","agent","agents"]},{"id":"token","g":"team","word":"Токен","text":"Единицата, в която се брои използването на AI: грубо няколко букви прочетен или написан текст. По-малко токени, повече останало от плана.","also":["токен","токена","токени","токените","token","tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Малка команда, която се изпълнява сама в определен момент, напр. когато започне AI сесия, за да чува екипът коментарите ти.","also":["hook","hook-ове","hook-а","hooks"]}]}};
